              DEFAULT: '#2A2A2A',
              strong: '#3A3A3A',
            },
            accent: {
              DEFAULT: '#3B82F6',
              hover: '#60A5FA',
              muted: 'rgba(59,130,246,0.15)',
            },
            amber: {
              DEFAULT: '#F59E0B',
              hover: '#FBBF24',
            },
            txt: {
              primary: '#FFFFFF',
              secondary: '#A0A0A0',
              muted: '#666666',
            }
          }
        }
      }
    }
  </script>
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }

    html {
      scroll-behavior: smooth;
      -webkit-font-smoothing: antialiased;
      -moz-osx-font-smoothing: grayscale;
    }

    body {
      background: #0A0A0A;
      color: #FFFFFF;
      font-family: 'Inter', system-ui, sans-serif;
      overflow-x: hidden;
    }

    ::selection {
      background: rgba(59, 130, 246, 0.3);
      color: #fff;
    }

    /* Hero Carousel */
    .hero-slide {
      opacity: 0;
      transition: opacity 0.8s cubic-bezier(0.4, 0, 0.2, 1);
      position: absolute;
      inset: 0;
    }
    .hero-slide.active {
      opacity: 1;
      z-index: 1;
    }
    .hero-slide .slide-content {
      transform: translateY(20px);
      opacity: 0;
      transition: all 0.6s cubic-bezier(0.4, 0, 0.2, 1) 0.3s;
    }
    .hero-slide.active .slide-content {
      transform: translateY(0);
      opacity: 1;
    }

    .hero-dot {
      width: 8px;
      height: 8px;
      border-radius: 50%;
      background: rgba(255, 255, 255, 0.3);
      transition: all 0.3s ease;
      cursor: pointer;
    }
    .hero-dot.active {
      background: #fff;
      width: 32px;
      border-radius: 4px;
    }

    /* Region Tabs */
    .region-tab {
      position: relative;
      padding: 0.75rem 1.5rem;
      color: #666;
      font-weight: 500;
      transition: color 0.3s ease;
      cursor: pointer;
      border: none;
      background: none;
      font-size: 0.9375rem;
      font-family: inherit;
      white-space: nowrap;
    }
    .region-tab::after {
      content: '';
      position: absolute;
      bottom: 0;
      left: 0;
      width: 100%;
      height: 2px;
      background: #3B82F6;
      transform: scaleX(0);
      transition: transform 0.3s ease;
    }
    .region-tab:hover { color: #A0A0A0; }
    .region-tab.active {
      color: #FFFFFF;
    }
    .region-tab.active::after {
      transform: scaleX(1);
    }

    /* Team Cards */
    .team-card {
      opacity: 0;
      transform: translateY(16px);
      transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
    }
    .team-card.visible {
      opacity: 1;
      transform: translateY(0);
    }

    /* Work Scroll */
    .work-scroll {
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      -webkit-overflow-scrolling: touch;
      scrollbar-width: none;
      cursor: grab;
    }
    .work-scroll::-webkit-scrollbar { display: none; }
    .work-scroll:active { cursor: grabbing; }
    .work-scroll > * {
      scroll-snap-align: start;
    }

    .work-card {
      transition: transform 0.3s ease;
    }
    .work-card:hover {
      transform: translateY(-4px);
    }
    .work-card:hover .work-img {
      transform: scale(1.05);
    }
    .work-img {
      transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
    }

    /* Insight Cards */
    .insight-card {
      transition: transform 0.3s ease, background 0.3s ease;
    }
    .insight-card:hover {
      transform: translateY(-2px);
      background: #1A1A1A;
    }

    /* Buttons */
    .btn-primary {
      background: #FFFFFF;
      color: #0A0A0A;
      padding: 0.875rem 2rem;
      font-weight: 600;
      font-size: 0.875rem;
      border-radius: 0;
      transition: all 0.2s ease;
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      text-decoration: none;
      letter-spacing: 0.02em;
    }
    .btn-primary:hover {
      background: #E5E5E5;
      transform: translateY(-1px);
    }

    .btn-outline {
      border: 1px solid #3A3A3A;
      color: #FFFFFF;
      padding: 0.875rem 2rem;
      font-weight: 500;
      font-size: 0.875rem;
      border-radius: 0;
      transition: all 0.2s ease;
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      text-decoration: none;
      background: transparent;
      letter-spacing: 0.02em;
    }
    .btn-outline:hover {
      border-color: #fff;
      background: rgba(255,255,255,0.05);
    }

    /* Cookie Banner */
    .cookie-banner {
      transform: translateY(100%);
      transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
    }
    .cookie-banner.show {
      transform: translateY(0);
    }

    /* Language Dropdown */
    .lang-dropdown {
      opacity: 0;
      visibility: hidden;
      transform: translateY(-8px);
      transition: all 0.2s ease;
    }
    .lang-dropdown.open {
      opacity: 1;
      visibility: visible;
      transform: translateY(0);
    }

    /* Mobile Nav */
    .mobile-nav {
      transform: translateX(100%);
      transition: transform 0.4s cubic-bezier(0.4, 0, 0.2, 1);
    }
    .mobile-nav.open {
      transform: translateX(0);
    }

    /* Scroll Reveal */
    .reveal {
      opacity: 0;
      transform: translateY(30px);
      transition: all 0.7s cubic-bezier(0.4, 0, 0.2, 1);
    }
    .reveal.visible {
      opacity: 1;
      transform: translateY(0);
    }

    /* Principle Number */
    .principle-num {
      font-size: 5rem;
      font-weight: 800;
      line-height: 1;
      background: linear-gradient(180deg, #2A2A2A 0%, #111111 100%);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }

    /* Nav Blur */
    .nav-blur {
      backdrop-filter: blur(20px);
      -webkit-backdrop-filter: blur(20px);
      background: rgba(10, 10, 10, 0.8);
    }

    /* Accent Link */
    .accent-link {
      color: #3B82F6;
      text-decoration: none;
      transition: color 0.2s ease;
    }
    .accent-link:hover { color: #60A5FA; }

    @media (max-width: 768px) {
      .hero-dot.active {
        width: 24px;
      }
    }
  </style>
</head>
<body>

  <!-- ═══════════════════════════ NAVIGATION ═══════════════════════════ -->
  <header class="fixed top-0 left-0 right-0 z-50 nav-blur border-b border-border-subtle">
    <div class="max-w-[1440px] mx-auto px-6 lg:px-12">
      <nav class="flex items-center justify-between h-16 lg:h-20" aria-label="Main navigation">
        <!-- Logo -->
        <a href="#" class="flex items-center gap-2 shrink-0">
          <div class="w-8 h-8 bg-white flex items-center justify-center">
            <span class="text-black font-extrabold text-sm">L</span>
          </div>
          <span class="text-white font-bold text-lg tracking-tight hidden sm:inline">Leap Studio</span>
        </a>

        <!-- Desktop Nav Links -->
        <div class="hidden lg:flex items-center gap-8">
          <a href="#insights" class="text-txt-secondary text-sm font-medium hover:text-white transition-colors">Insights</a>
          <a href="#work" class="text-txt-secondary text-sm font-medium hover:text-white transition-colors">Work</a>
          <a href="#services" class="text-txt-secondary text-sm font-medium hover:text-white transition-colors">Services</a>
          <a href="#culture" class="text-txt-secondary text-sm font-medium hover:text-white transition-colors">Culture</a>
          <a href="#careers" class="text-txt-secondary text-sm font-medium hover:text-white transition-colors">Make Your Mark</a>
        </div>

        <!-- Right Side -->
        <div class="flex items-center gap-4">
          <!-- Language Selector -->
          <div class="relative" id="lang-selector">
            <button onclick="toggleLang()" class="flex items-center gap-1.5 text-sm text-txt-secondary hover:text-white transition-colors px-2 py-1" aria-haspopup="true" aria-expanded="false">
              <i data-lucide="globe" class="w-4 h-4"></i>
              <span class="hidden sm:inline">EN</span>
              <i data-lucide="chevron-down" class="w-3 h-3"></i>
            </button>
            <div class="lang-dropdown absolute right-0 top-full mt-2 w-48 bg-surface-overlay border border-border rounded-lg shadow-2xl shadow-black/50 overflow-hidden" id="lang-dropdown">
              <button onclick="selectLang('en')" class="w-full px-4 py-3 text-left text-sm hover:bg-surface-hover transition-colors flex items-center justify-between text-white">
                Global EN
                <span class="text-accent text-xs" id="lang-check-en">&#10003;</span>
              </button>
              <button onclick="selectLang('fr')" class="w-full px-4 py-3 text-left text-sm hover:bg-surface-hover transition-colors flex items-center justify-between text-txt-secondary hover:text-white">
                France FR
                <span class="text-accent text-xs hidden" id="lang-check-fr">&#10003;</span>
              </button>
              <button onclick="selectLang('cn')" class="w-full px-4 py-3 text-left text-sm hover:bg-surface-hover transition-colors flex items-center justify-between text-txt-secondary hover:text-white">
                China CN
                <span class="text-accent text-xs hidden" id="lang-check-cn">&#10003;</span>
              </button>
            </div>
          </div>

          <!-- Contact CTA -->
          <a href="#contact" class="hidden md:inline-flex items-center gap-2 bg-white text-black text-sm font-semibold px-5 py-2.5 hover:bg-gray-200 transition-colors">
            Contact Us
          </a>

          <!-- Mobile Hamburger -->
          <button onclick="toggleMobileNav()" class="lg:hidden flex flex-col gap-1.5 p-2" aria-label="Toggle navigation" id="hamburger">
            <span class="block w-5 h-0.5 bg-white transition-all origin-center" id="ham-1"></span>
            <span class="block w-5 h-0.5 bg-white transition-all" id="ham-2"></span>
            <span class="block w-5 h-0.5 bg-white transition-all origin-center" id="ham-3"></span>
          </button>
        </div>
      </nav>
    </div>
  </header>

  <!-- Mobile Nav Overlay -->
  <div class="mobile-nav fixed inset-0 z-40 bg-surface flex flex-col pt-20 px-8" id="mobile-nav">
    <div class="flex flex-col gap-6 py-8">
      <a href="#insights" onclick="toggleMobileNav()" class="text-3xl font-semibold text-white hover:text-accent transition-colors">Insights</a>
      <a href="#work" onclick="toggleMobileNav()" class="text-3xl font-semibold text-white hover:text-accent transition-colors">Work</a>
      <a href="#services" onclick="toggleMobileNav()" class="text-3xl font-semibold text-white hover:text-accent transition-colors">Services</a>
      <a href="#culture" onclick="toggleMobileNav()" class="text-3xl font-semibold text-white hover:text-accent transition-colors">Culture</a>
      <a href="#careers" onclick="toggleMobileNav()" class="text-3xl font-semibold text-white hover:text-accent transition-colors">Make Your Mark</a>
      <a href="#contact" onclick="toggleMobileNav()" class="text-3xl font-semibold text-white hover:text-accent transition-colors">Contact Us</a>
    </div>
    <div class="mt-auto pb-8 flex flex-col gap-3 text-txt-secondary text-sm">
      <button onclick="selectLang('en'); toggleMobileNav();" class="text-left hover:text-white transition-colors">Global EN</button>
      <button onclick="selectLang('fr'); toggleMobileNav();" class="text-left hover:text-white transition-colors">France FR</button>
      <button onclick="selectLang('cn'); toggleMobileNav();" class="text-left hover:text-white transition-colors">China CN</button>
    </div>
  </div>

  <main>
    <!-- ═══════════════════════════ HERO CAROUSEL ═══════════════════════════ -->
    <section class="relative h-screen min-h-[600px] max-h-[900px] overflow-hidden" id="hero" aria-label="Featured content carousel">
      <!-- Slides -->
      <div class="relative h-full" id="hero-slides">
        <!-- Slide 1 -->
        <div class="hero-slide active" data-slide="0">
          <div class="absolute inset-0">
            <img src="https://images.unsplash.com/photo-1451187580459-43490279c0fa?w=1920&h=1080&fit=crop&auto=format" alt="Synthetic realities abstract" class="w-full h-full object-cover" loading="eager">
            <div class="absolute inset-0 bg-gradient-to-r from-black/80 via-black/50 to-black/30"></div>
          </div>
          <div class="slide-content relative z-10 h-full flex items-end pb-24 lg:pb-32">
            <div class="max-w-[1440px] mx-auto px-6 lg:px-12 w-full">
              <p class="text-accent text-sm font-semibold uppercase tracking-widest mb-4">Featured Report</p>
              <h1 class="text-4xl md:text-5xl lg:text-6xl xl:text-7xl font-bold leading-[1.05] mb-6 max-w-3xl">Futurescape:<br>Synthetic Realities</h1>
              <p class="text-lg text-txt-secondary max-w-xl mb-8">Welcome to the Futurescape. Discover trends and insights on the future of human-AI chemistry.</p>
              <a href="#" class="btn-primary">Read the report <i data-lucide="arrow-right" class="w-4 h-4"></i></a>
            </div>
          </div>
        </div>

        <!-- Slide 2 -->
        <div class="hero-slide" data-slide="1">
          <div class="absolute inset-0">
            <img src="https://images.unsplash.com/photo-1485827404703-89b55fcc595e?w=1920&h=1080&fit=crop&auto=format" alt="Robot design concept" class="w-full h-full object-cover" loading="lazy">
            <div class="absolute inset-0 bg-gradient-to-r from-black/80 via-black/50 to-black/30"></div>
          </div>
          <div class="slide-content relative z-10 h-full flex items-end pb-24 lg:pb-32">
            <div class="max-w-[1440px] mx-auto px-6 lg:px-12 w-full">
              <p class="text-accent text-sm font-semibold uppercase tracking-widest mb-4">Case Study</p>
              <h1 class="text-4xl md:text-5xl lg:text-6xl xl:text-7xl font-bold leading-[1.05] mb-6 max-w-3xl">Designing Robots for Human Spaces</h1>
              <p class="text-lg text-txt-secondary max-w-xl mb-8">Meet 'Aura,' a concept from Leap Studio that offers a human-centered approach to physical AI.</p>
              <a href="#" class="btn-primary">Explore the work <i data-lucide="arrow-right" class="w-4 h-4"></i></a>
            </div>
          </div>
        </div>

        <!-- Slide 3 -->
        <div class="hero-slide" data-slide="2">
          <div class="absolute inset-0">
            <img src="https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=1920&h=1080&fit=crop&auto=format" alt="Clinical care visualization" class="w-full h-full object-cover" loading="lazy">
            <div class="absolute inset-0 bg-gradient-to-r from-black/80 via-black/50 to-black/30"></div>
          </div>
          <div class="slide-content relative z-10 h-full flex items-end pb-24 lg:pb-32">
            <div class="max-w-[1440px] mx-auto px-6 lg:px-12 w-full">
              <p class="text-accent text-sm font-semibold uppercase tracking-widest mb-4">Thought Leadership</p>
              <h1 class="text-4xl md:text-5xl lg:text-6xl xl:text-7xl font-bold leading-[1.05] mb-6 max-w-3xl">Amplifying Clinical Care with AI</h1>
              <p class="text-lg text-txt-secondary max-w-xl mb-8">Examining how service design helps experts understand the healthcare ecosystem.</p>
              <a href="#" class="btn-primary">Explore now <i data-lucide="arrow-right" class="w-4 h-4"></i></a>
            </div>
          </div>
        </div>

        <!-- Slide 4 -->
        <div class="hero-slide" data-slide="3">
          <div class="absolute inset-0">
            <img src="https://images.unsplash.com/photo-1478737270239-2f02b77fc618?w=1920&h=1080&fit=crop&auto=format" alt="Podcast studio" class="w-full h-full object-cover" loading="lazy">
            <div class="absolute inset-0 bg-gradient-to-r from-black/80 via-black/50 to-black/30"></div>
          </div>
          <div class="slide-content relative z-10 h-full flex items-end pb-24 lg:pb-32">
            <div class="max-w-[1440px] mx-auto px-6 lg:px-12 w-full">
              <p class="text-accent text-sm font-semibold uppercase tracking-widest mb-4">Design Mind Leapcast Ep. 55</p>
              <h1 class="text-4xl md:text-5xl lg:text-6xl xl:text-7xl font-bold leading-[1.05] mb-6 max-w-3xl">What Makes a Product Great?</h1>
              <p class="text-lg text-txt-secondary max-w-xl mb-8">Peter Hallstr&ouml;m, Global Head of Design at Lumina Health, discusses the evolution of product design and the role of design leadership.</p>
              <a href="#" class="btn-primary">Listen now <i data-lucide="arrow-right" class="w-4 h-4"></i></a>
            </div>
          </div>
        </div>

        <!-- Slide 5 -->
        <div class="hero-slide" data-slide="4">
          <div class="absolute inset-0">
            <img src="https://images.unsplash.com/photo-1460925895917-afdab827c52f?w=1920&h=1080&fit=crop&auto=format" alt="Data analysis" class="w-full h-full object-cover" loading="lazy">
            <div class="absolute inset-0 bg-gradient-to-r from-black/80 via-black/50 to-black/30"></div>
          </div>
          <div class="slide-content relative z-10 h-full flex items-end pb-24 lg:pb-32">
            <div class="max-w-[1440px] mx-auto px-6 lg:px-12 w-full">
              <p class="text-accent text-sm font-semibold uppercase tracking-widest mb-4">Research Report</p>
              <h1 class="text-4xl md:text-5xl lg:text-6xl xl:text-7xl font-bold leading-[1.05] mb-6 max-w-3xl">From Complexity to Clarity</h1>
              <p class="text-lg text-txt-secondary max-w-xl mb-8">Dive into new research on how CMOs can reclaim marketing to build competitive edge.</p>
              <a href="#" class="btn-primary">Read the report <i data-lucide="arrow-right" class="w-4 h-4"></i></a>
            </div>
          </div>
        </div>
      </div>

      <!-- Hero Controls -->
      <div class="absolute bottom-8 lg:bottom-12 right-6 lg:right-12 z-20 flex items-center gap-6">
        <div class="flex items-center gap-2" id="hero-dots" role="tablist" aria-label="Slide navigation">
          <button class="hero-dot active" data-dot="0" role="tab" aria-selected="true" aria-label="Slide 1"></button>
          <button class="hero-dot" data-dot="1" role="tab" aria-selected="false" aria-label="Slide 2"></button>
          <button class="hero-dot" data-dot="2" role="tab" aria-selected="false" aria-label="Slide 3"></button>
          <button class="hero-dot" data-dot="3" role="tab" aria-selected="false" aria-label="Slide 4"></button>
          <button class="hero-dot" data-dot="4" role="tab" aria-selected="false" aria-label="Slide 5"></button>
        </div>
        <div class="flex items-center gap-2">
          <button onclick="heroNav(-1)" class="w-10 h-10 border border-border-strong flex items-center justify-center hover:bg-white/10 transition-colors" aria-label="Previous slide">
            <i data-lucide="chevron-left" class="w-4 h-4"></i>
          </button>
          <button onclick="heroNav(1)" class="w-10 h-10 border border-border-strong flex items-center justify-center hover:bg-white/10 transition-colors" aria-label="Next slide">
            <i data-lucide="chevron-right" class="w-4 h-4"></i>
          </button>
        </div>
      </div>
    </section>

    <!-- ═══════════════════════════ TEAM / GLOBAL STUDIOS ═══════════════════════════ -->
    <section class="py-24 lg:py-32" id="culture" aria-label="Global studios">
      <div class="max-w-[1440px] mx-auto px-6 lg:px-12">
        <div class="reveal mb-16">
          <p class="text-accent text-sm font-semibold uppercase tracking-widest mb-4">Global Studios</p>
          <h2 class="text-3xl md:text-4xl lg:text-5xl font-bold mb-4">Welcome to the studio</h2>
          <p class="text-txt-secondary text-lg max-w-2xl">Meet the team making an impact for leading brands around the globe.</p>
        </div>

        <!-- Region Tabs -->
        <div class="reveal flex gap-1 border-b border-border mb-12 overflow-x-auto" role="tablist" aria-label="Select region">
          <button class="region-tab active" data-region="north-america" role="tab" aria-selected="true" onclick="switchRegion('north-america')">North America</button>
          <button class="region-tab" data-region="asia" role="tab" aria-selected="false" onclick="switchRegion('asia')">Asia</button>
          <button class="region-tab" data-region="europe" role="tab" aria-selected="false" onclick="switchRegion('europe')">Europe</button>
          <button class="region-tab" data-region="oceania" role="tab" aria-selected="false" onclick="switchRegion('oceania')">Oceania</button>
        </div>

        <!-- Team Cards Container -->
        <div class="grid grid-cols-1 md:grid-cols-2 gap-8" id="team-cards" role="tabpanel" aria-label="Team members">
          <!-- Cards injected by JS -->
        </div>
      </div>
    </section>

    <!-- ═══════════════════════════ WORK SHOWCASE ═══════════════════════════ -->
    <section class="py-24 lg:py-32 border-t border-border-subtle" id="work" aria-label="Client work">
      <div class="max-w-[1440px] mx-auto px-6 lg:px-12">
        <div class="reveal flex flex-col md:flex-row md:items-end md:justify-between gap-6 mb-16">
          <div>
            <p class="text-accent text-sm font-semibold uppercase tracking-widest mb-4">Selected Projects</p>
            <h2 class="text-3xl md:text-4xl lg:text-5xl font-bold mb-4">Our work</h2>
            <p class="text-txt-secondary text-lg max-w-2xl">Reinvent your business and realize exceptional experiences that win hearts and move markets.</p>
          </div>
          <div class="flex items-center gap-2 shrink-0">
            <button onclick="scrollWork(-1)" class="w-12 h-12 border border-border-strong flex items-center justify-center hover:bg-white/10 transition-colors" aria-label="Scroll work left">
