    function goToSlide(idx) {
      const slides = document.querySelectorAll('.hero-slide');
      const dots = document.querySelectorAll('.hero-dot');
      slides.forEach(s => s.classList.remove('active'));
      dots.forEach(d => { d.classList.remove('active'); d.setAttribute('aria-selected', 'false'); });
      slides[idx].classList.add('active');
      dots[idx].classList.add('active');
      dots[idx].setAttribute('aria-selected', 'true');
      currentSlide = idx;
    }

    function heroNav(dir) {
      let next = (currentSlide + dir + totalSlides) % totalSlides;
      goToSlide(next);
      resetHeroInterval();
    }

    function resetHeroInterval() {
      clearInterval(heroInterval);
      heroInterval = setInterval(() => heroNav(1), 5000);
    }

    document.querySelectorAll('.hero-dot').forEach(dot => {
