      el.scrollBy({ left: dir * cardWidth, behavior: 'smooth' });
    }

    // Drag to scroll
    const workScroll = document.getElementById('work-scroll');
    let isDown = false, startX, scrollLeft;
    workScroll.addEventListener('mousedown', (e) => {
      isDown = true;
      startX = e.pageX - workScroll.offsetLeft;
      scrollLeft = workScroll.scrollLeft;
    });
    workScroll.addEventListener('mouseleave', () => isDown = false);
    workScroll.addEventListener('mouseup', () => isDown = false);
    workScroll.addEventListener('mousemove', (e) => {
      if (!isDown) return;
      e.preventDefault();
      const x = e.pageX - workScroll.offsetLeft;
      workScroll.scrollLeft = scrollLeft - (x - startX);
    });

